function generateSliderImages(e,t,a){function n(){l=(l+1)%r,d.style.transform=`translateX(-${100*l}%)`}let l=0;const i=4,r=Math.ceil(a/i),d=document.getElementById(t);d.innerHTML="";for(let t=0;t<a;t+=i){const n=document.createElement("div");n.className="image-slider-slide-image-container";for(let l=0;l<i&&t+l<a;l++){const a=document.createElement("div");a.className="image-slider-slide-image";const i=document.createElement("img");i.src=e+`image${t+l+1}.avif`,i.alt=`image${t+l+1}`,i.loading="lazy",a.appendChild(i),n.appendChild(a)}d.appendChild(n)}setInterval(n,5e3)}async function loadImageSlider(){try{const e=document.querySelectorAll(".image-slider-placeholder");e.forEach(async e=>{const t=await fetch("/assets/components/image-slider.html"),a=await t.text(),n=e.dataset.id,l=e.dataset.folder,i=parseInt(e.dataset.numberOfImages);e.innerHTML=a;const r=e.querySelector(".image-slider-track");r.id=n,generateSliderImages(l,n,i)})}catch(e){console.error("Error loading title:",e)}}document.addEventListener("DOMContentLoaded",loadImageSlider);